from helpers import D, src, DSM
CARDS = []
NSDUH = src("src-nsduh-2023", "Key substance use and mental health indicators in the United States: results from the 2023 National Survey on Drug Use and Health", "SAMHSA", "https://www.samhsa.gov/data/release/2023-national-survey-drug-use-and-health-nsduh-releases", 2024, note="Figures seen via secondary summaries; confirm on the SAMHSA release page.")
NIDA = src("src-nida-addiction", "Drugs, Brains, and Behavior: The Science of Addiction", "National Institute on Drug Abuse (NIDA)", "https://nida.nih.gov/publications/drugs-brains-behavior-science-addiction", note="Not opened.")
NIDA_TX = src("src-nida-treatment", "Treatment and Recovery", "National Institute on Drug Abuse (NIDA)", "https://nida.nih.gov/research-topics/treatment", note="Not opened; NIDA's current treatment page replaces the archived 'Principles' guide.")
NICE115 = src("src-nice-cg115", "Alcohol-use disorders: diagnosis, assessment and management of harmful drinking and alcohol dependence (CG115)", "NICE", "https://www.nice.org.uk/guidance/cg115", 2011, seen=True)
SAMHSA_HELP = src("src-samhsa-helpline", "SAMHSA National Helpline", "SAMHSA", "https://www.samhsa.gov/find-help/helplines/national-helpline", note="Number 1-800-662-4357 confirmed via a university page; official URL not opened.")
VIS = lambda prompt, alt: {"color_token": "substance", "icon": "anchor", "illustration_prompt": prompt, "alt_text": alt}
ELEV = lambda extra=[]: {"sensitivity_level": "elevated", "show_crisis_strip": True, "content_notes": ["No dosing, sourcing, or 'how to use' detail. Harm-reduction pointers only to official organizations.", "Crisis strip with substance helplines required."] + extra}
REV = lambda qs=[], clin=False: {"last_researched": D, "reading_grade_estimate": 0, "reading_grade_method": "Flesch-Kincaid grade, computed on all reader-facing text", "verification_status": "needs_human_review" if clin else "needs_verification", "needs_clinician_signoff": clin, "open_questions": qs}
RECOVERY = ["smart-recovery-meetings", "aa-online-intergroup", "virtual-na", "samhsa-national-helpline"]

CARDS.append({
 "topic_id": "substance-use-disorders-overview", "official_name": "Substance Use Disorders (explainer)", "plain_title": "What 'use disorder' means, and what recovery looks like",
 "also_known_as": ["addiction", "substance dependence (older term)", "SUD"], "chapter_id": "substance", "card_type": "explainer", "icd10cm_code": "n/a (F10–F19 by substance)", "language_convention": "person-first",
 "language_convention_note": "'A person with a substance use disorder', 'in recovery'. Never 'addict', 'alcoholic', 'junkie', 'user', or 'clean/dirty'. Many people in 12-step programmes call themselves 'alcoholics' or 'addicts' by choice; that's their call, not ours.",
 "one_liner": "A pattern of using a substance that a person can't control and keeps going despite the harm it causes.",
 "in_simple_words": "A substance use disorder isn't about how much or how often someone uses, or about weakness or bad character. It's a pattern: wanting to cut down and not managing to, cravings, using more than planned, needing more for the same effect, withdrawal when stopping, and carrying on even as health, work, relationships, or safety are harmed. The DSM grades it mild, moderate, or severe. The brain changes involved are real and so is recovery; millions of people are in it.",
 "what_it_can_feel_like": ["I kept a list of reasons to stop and used anyway. That's when I knew it wasn't a choice anymore.", "Everyone pictured a guy on a park bench. I had a job and a mortgage and a bottle in the desk drawer.", "Recovery wasn't one decision. It was a thousand small ones, with a lot of people holding me up."],
 "common_signs": ["Using more, or for longer, than intended", "Wanting to cut down and not managing to", "Strong cravings", "Needing more for the same effect, or withdrawal when stopping", "Giving up activities, or failing at work, school, or home because of use", "Continuing despite harm to health, safety, or relationships"],
 "myths_vs_facts": [
  {"myth": "Addiction is a choice or a moral failing.", "fact": "Nobody chooses a use disorder. Genetics, trauma, mental health, and environment all play in, and the brain's reward system is changed by repeated use."},
  {"myth": "You have to hit rock bottom first.", "fact": "People recover at every stage. Earlier is easier, and waiting for 'rock bottom' can be fatal."},
  {"myth": "Relapse means treatment failed.", "fact": "Relapse is common in a chronic condition, like a flare-up in asthma. It's a signal to adjust support, not to give up."},
  {"myth": "Medication for addiction is just swapping one drug for another.", "fact": "Medications for opioid and alcohol use disorders are among the most effective treatments in medicine and dramatically cut deaths."}],
 "how_common": {"plain": "About 1 in 6 people aged 12 and over in the US had a substance use disorder in the past year. Only about 1 in 4 of those who needed treatment got it.",
  "figure": "48.5 million people (17.1%) aged 12+ with a past-year substance use disorder; about one in four of those needing treatment received it (NSDUH 2023)", "source_ref": "src-nsduh-2023"},
 "what_helps": {"plain_summary": "Treatment works and comes in many forms: talking therapies like CBT and motivational interviewing, medications for alcohol, opioid, and tobacco use disorders (prescribed and monitored by a doctor), peer and mutual-aid groups (12-step, SMART Recovery, and others), and support with housing, work, and mental health. Medically supervised withdrawal is needed for some substances. Harm reduction, like naloxone and needle programmes, keeps people alive while they're not ready to stop. Recovery is a long game and support at every stage matters.",
  "evidence_based_options": ["CBT, motivational interviewing, and contingency management", "Medications for alcohol, opioid, and tobacco use disorders, prescribed and monitored by a doctor", "Mutual-aid groups: 12-step fellowships, SMART Recovery, and others", "Harm-reduction services and treatment for co-occurring mental health conditions"],
  "self_help_that_supports_care": ["Telling one person, or calling a helpline, as a first step", "Finding a meeting, online or local, and going more than once", "Knowing your triggers: people, places, feelings, times", "Treating sleep, food, and the other mental health stuff too"],
  "guideline_refs": ["src-nida-treatment"]},
 "when_to_reach_out": "If you've tried to cut down and can't, or using is costing you things you care about, talk to a doctor or a substance helpline; you don't need to be 'bad enough'. Get emergency help for an overdose, a seizure, or severe withdrawal. Never stop alcohol or benzodiazepines suddenly without medical advice.",
 "is_not": "Using a substance, even regularly, isn't automatically a disorder. Physical dependence on a prescribed medicine taken as directed isn't addiction. Occasional heavy use without loss of control or harm is risky but not a diagnosis.",
 "hope_note": "Most people with a substance use disorder eventually recover, many without formal treatment and many with it. Recovery communities are among the warmest places on earth.",
 "in_young_people": "Substance use that starts in the early teens carries higher risk of a later disorder, because the brain is still developing. Young people's treatment involves family and school and focuses on the reasons behind use.",
 "across_cultures": "Alcohol and drug norms differ enormously between cultures and religions, and so does stigma. In some communities seeking help means family shame; in others, faith-based recovery is central. Services that respect this reach more people. Indigenous communities in several countries have developed their own culturally grounded recovery programmes.",
 "sub_sections": [{"title": "Severity", "text": "Mild, moderate, or severe, depending on how many of the eleven DSM criteria apply. 'Severe' is roughly what people mean by addiction."},
  {"title": "Intoxication and withdrawal", "text": "Each substance has its own intoxication and withdrawal syndromes with their own codes. Withdrawal from alcohol, benzodiazepines, and similar sedatives can be medically dangerous."},
  {"title": "Remission", "text": "'Early remission' means three to twelve months without meeting criteria (apart from craving); 'sustained remission' means twelve months or more."}],
 "related_topics": ["alcohol-use-disorder", "opioid-use-disorder", "cannabis-use-disorder", "stimulant-use-disorder", "tobacco-use-disorder", "gambling-disorder", "substance-medication-induced-mental-disorders", "major-depressive-disorder", "posttraumatic-stress-disorder"],
 "glossary_terms": ["tolerance", "withdrawal", "craving", "dependence", "relapse", "recovery", "harm-reduction", "twelve-step", "smart-recovery", "motivational-interviewing", "addiction-pop", "stigma-words"],
 "safety": ELEV(),
 "visual": VIS("Soft line illustration of a circle of chairs in a community hall with people of different ages chatting over coffee before a meeting, a notice board with a 'welcome' sign. Pastel navy and sand. No bottles, pills, or needles.", "People of different ages chat over coffee in a circle of chairs in a community hall before a meeting."),
 "communities": RECOVERY + ["reddit-r-stopdrinking", "al-anon-electronic-meetings"],
 "sources": [DSM("Substance-Related and Addictive Disorders"), NSDUH, NIDA, NIDA_TX, SAMHSA_HELP],
 "review": REV(["Confirm NSDUH 2023 figures on the SAMHSA page.", "Confirm SAMHSA helpline URL."])})

def sub_card(tid, name, title, aka, code, one, simple, feel, signs, myths, how, helps, reach, isnot, hope, young, cult, subs, related, gloss, comms, srcs, qs, extra_notes=[], clin=False, sens=None):
    card = {"topic_id": tid, "official_name": name, "plain_title": title, "also_known_as": aka, "chapter_id": "substance", "card_type": "condition", "icd10cm_code": code,
     "language_convention": "person-first", "one_liner": one, "in_simple_words": simple, "what_it_can_feel_like": feel, "common_signs": signs, "myths_vs_facts": myths,
     "how_common": how, "what_helps": helps, "when_to_reach_out": reach, "is_not": isnot, "hope_note": hope, "related_topics": related, "glossary_terms": gloss,
     "safety": sens or ELEV(extra_notes), "visual": VIS(*comms["vis"]), "communities": comms["ids"], "sources": srcs, "review": REV(qs, clin)}
    if young: card["in_young_people"] = young
    if cult: card["across_cultures"] = cult
    if subs: card["sub_sections"] = subs
    return card

CARDS.append(sub_card("alcohol-use-disorder", "Alcohol Use Disorder", "When drinking has taken control", ["alcoholism (older term)", "alcohol dependence", "problem drinking"], "F10.10 (mild) / F10.20 (moderate, severe)",
 "Drinking that a person can't control and keeps up despite harm to health, work, safety, or relationships.",
 "Alcohol use disorder ranges from mild to severe. It's not about what you drink or whether you drink daily; it's about losing control: drinking more than planned, failing to cut down, craving, needing more, withdrawal, and carrying on despite the damage. It's one of the most common mental health conditions and one of the most hidden. Stopping suddenly after heavy daily drinking can be dangerous, so medical advice matters. Treatment works, and millions of people are in recovery.",
 ["I never drank in the morning, so I told myself I was fine. I just couldn't stop once I started.", "The shakes in the morning were the thing I couldn't explain away.", "A year sober. I'm not 'cured'. I'm free, one day at a time, with a lot of help."],
 ["Drinking more, or more often, than intended", "Trying to cut down and not managing", "Cravings, or needing more to feel the same effect", "Shakes, sweats, anxiety, or poor sleep when not drinking", "Drinking despite health, money, work, or relationship problems", "Hiding drinking or feeling defensive about it"],
 [{"myth": "You're only an alcoholic if you drink in the morning or lose your job.", "fact": "Most people with alcohol use disorder are working, parenting, and functioning. 'High-functioning' doesn't mean no harm."},
  {"myth": "Willpower is all you need.", "fact": "Alcohol changes the brain's reward and stress systems. Treatment, medication, and support beat willpower alone."},
  {"myth": "Stopping cold turkey is the brave way.", "fact": "For heavy daily drinkers, sudden stopping can cause seizures and can be fatal. Medically supervised withdrawal is the safe way."}],
 {"plain": "About 1 in 10 people aged 12 and over in the US had alcohol use disorder in the past year, nearly 29 million people.", "figure": "28.9 million people (10.2%) aged 12+ with past-year alcohol use disorder (NSDUH 2023)", "source_ref": "src-nsduh-2023"},
 {"plain_summary": "Options range from brief advice and self-help for milder problems to specialist treatment for dependence. Talking therapies (CBT, motivational approaches, behavioural couples therapy) help. Three medications, prescribed and monitored by a doctor, reduce cravings or relapse. Medically supervised withdrawal is needed for heavy dependence. Mutual-aid groups like AA and SMART Recovery support long-term recovery, and family programmes like Al-Anon support relatives.",
  "evidence_based_options": ["Brief interventions and guided self-help for harmful drinking", "CBT, motivational enhancement, and behavioural couples therapy", "Medications to support abstinence or reduce drinking, prescribed and monitored by a doctor", "Medically supervised withdrawal, then relapse prevention and mutual-aid groups"],
  "self_help_that_supports_care": ["Tracking drinks honestly for two weeks", "Alcohol-free days, then stretches, with support", "Telling people you're cutting down so they stop pouring", "Meetings, online or local; try several"],
  "guideline_refs": ["src-nice-cg115"]},
 "If you've tried to cut down and can't, drink to cope, or get shaky or anxious when you stop, talk to a doctor or an alcohol helpline. Do not stop suddenly after heavy daily drinking without medical advice. Get emergency help for seizures, confusion, or hallucinations when stopping.",
 "Drinking above recommended limits is risky but isn't a disorder on its own. Binge drinking at parties, without loss of control the rest of the time, is harmful but different from dependence.",
 "People recover from severe alcohol use disorder every day. Recovery communities are full of people who thought they were the exception.",
 "Teenage drinking is common and most teens don't develop a disorder, but early heavy drinking raises the risk. Family involvement and treating the anxiety or trauma underneath matter most.",
 "Drinking norms vary hugely: alcohol is forbidden in some faiths and central to social life in some cultures. Shame about drinking problems is universal. Culturally specific recovery programmes exist in many communities, including Indigenous-led ones.",
 [{"title": "Alcohol intoxication and withdrawal", "icd10cm_code": "F10.x20 / F10.x30–x31 (varies)", "text": "Intoxication is being drunk. Withdrawal, after heavy regular use, ranges from shakes and anxiety to seizures and delirium tremens, a medical emergency."},
  {"title": "Alcohol-induced mental disorders", "text": "Heavy drinking can cause depression, anxiety, psychosis, sleep problems, and lasting memory damage (including Wernicke-Korsakoff syndrome). Many improve with abstinence."}],
 ["substance-use-disorders-overview", "major-depressive-disorder", "generalized-anxiety-disorder", "posttraumatic-stress-disorder", "social-anxiety-disorder", "neurocognitive-disorder-other-causes"],
 ["withdrawal", "tolerance", "craving", "detox", "twelve-step", "smart-recovery", "hangxiety", "sober-curious", "relapse-prevention"],
 {"ids": ["reddit-r-stopdrinking", "aa-online-intergroup", "smart-recovery-meetings", "al-anon-electronic-meetings", "drinkline-uk", "samhsa-national-helpline"],
  "vis": ("Soft line illustration of a person at a sunrise run with a friend, water bottles, a '1 year' token on a keyring. Pastel navy and gold. No bottles or glasses.", "Two friends on a sunrise run with water bottles, a one-year token hanging from a keyring.")},
 [DSM("Substance-Related and Addictive Disorders"), NSDUH, NICE115, src("src-drinkline", "Drinkline (national alcohol helpline, England)", "NHS / Drinkline", "https://www.nhs.uk/live-well/alcohol-advice/alcohol-support/", note="Number 0300 123 1110 seen on NHS practice pages; official page not opened.")],
 ["Confirm Drinkline details on the NHS page."]))

CARDS.append(sub_card("opioid-use-disorder", "Opioid Use Disorder", "When painkillers or heroin have taken control", ["opioid addiction", "opioid dependence", "heroin addiction"], "F11.10 (mild) / F11.20 (moderate, severe)",
 "A pattern of opioid use, whether prescription painkillers, heroin, or fentanyl, that a person can't control despite serious harm.",
 "Opioids include prescription painkillers, heroin, and fentanyl. Opioid use disorder is when use becomes hard to control: cravings, needing more, withdrawal when stopping, and continuing despite harm. It can start with a legitimate prescription. The biggest danger is overdose, which stops breathing and is now often caused by fentanyl mixed into other drugs. Naloxone reverses overdoses. Medication treatment is highly effective and cuts the risk of death in half. Recovery is real and common.",
 ["It started with pills after surgery. By the time I noticed, stopping meant being sick for days.", "Methadone isn't 'still using'. It's the reason I have a job and a daughter who trusts me.", "I carry naloxone now. I've used it twice. Both people are alive."],
 ["Using opioids more or longer than intended, or wanting to stop and not managing", "Strong cravings; needing more for the same effect", "Withdrawal: aches, sweats, stomach cramps, anxiety, restlessness when stopping", "Spending a lot of time getting, using, or recovering", "Using despite harm to health, relationships, work, or safety", "Switching from pills to other forms to avoid withdrawal"],
 [{"myth": "Medication treatment just replaces one addiction with another.", "fact": "Buprenorphine and methadone, taken as prescribed, stabilize the brain, stop withdrawal and craving, and halve the risk of death. They are treatment."},
  {"myth": "People who overdose chose this.", "fact": "Most overdoses are accidental, often from fentanyl hidden in other drugs. Naloxone and drug checking save lives."},
  {"myth": "Detox is the cure.", "fact": "Detox alone has very high relapse and overdose rates, because tolerance drops. Ongoing treatment is what works."}],
 {"plain": "About 2 in 100 people aged 12 and over in the US had opioid use disorder in the past year, nearly 6 million people.", "figure": "5.7 million people (2.0%) aged 12+ with past-year opioid use disorder (NSDUH 2023)", "source_ref": "src-nsduh-2023"},
 {"plain_summary": "Medications for opioid use disorder, mainly buprenorphine and methadone, prescribed and monitored by a doctor or clinic, are the most effective treatment and should be offered to everyone with the condition. Naltrexone is an option for some. Counselling, peer support, and help with housing and work add to recovery. Naloxone, free from pharmacies and services in many countries, reverses overdoses and everyone at risk, and their families, should carry it. Detox without follow-on treatment is dangerous.",
  "evidence_based_options": ["Buprenorphine or methadone treatment, prescribed and monitored by a doctor or clinic", "Extended-release naltrexone for some people", "Counselling, CBT, and contingency management alongside medication", "Naloxone, harm-reduction services, and peer support"],
  "self_help_that_supports_care": ["Carrying naloxone and telling the people around you how to use it", "Never using alone; many areas have a 'never use alone' phone line", "Finding a prescriber or clinic; waits are often shorter than feared", "Meetings and peer support, including Narcotics Anonymous and SMART Recovery"],
  "guideline_refs": ["src-nida-treatment"]},
 "If you're using opioids in a way you can't control, or dreading withdrawal, ask a doctor, clinic, or helpline about medication treatment today. Call emergency services for any suspected overdose (slow breathing, can't be woken, blue lips) and give naloxone if you have it.",
 "Taking prescribed opioids for pain as directed, even with physical dependence, isn't opioid use disorder. Physical dependence can be tapered under medical care.",
 "With medication treatment, people with opioid use disorder go back to work, rebuild families, and live long lives. The treatment exists; the task is reaching it.",
 "Opioid use in teens often starts with pills from a family medicine cabinet. Medication treatment is approved for older teens, and early treatment with family involvement has the best outcomes.",
 "The opioid crisis looks different in different countries: prescription-driven in North America, heroin-driven in many others. Access to medication treatment varies hugely. In some communities, stigma around methadone keeps people from the treatment most likely to save them.",
 [{"title": "Opioid intoxication and withdrawal", "icd10cm_code": "F11.x2 / F11.x3 (varies)", "text": "Intoxication can cause dangerous slowing of breathing. Withdrawal is intensely unpleasant but not usually life-threatening on its own; the danger is relapsing afterwards with lowered tolerance."}],
 ["substance-use-disorders-overview", "sedative-hypnotic-anxiolytic-use-disorder", "alcohol-use-disorder", "major-depressive-disorder", "posttraumatic-stress-disorder", "somatic-symptom-disorder"],
 ["medication-for-opioid-use-disorder", "naloxone", "overdose", "withdrawal", "harm-reduction", "dependence", "twelve-step"],
 {"ids": ["reddit-r-opiatesrecovery", "virtual-na", "smart-recovery-meetings", "samhsa-national-helpline", "frank-uk"],
  "vis": ("Soft line illustration of a person collecting a prescription at a pharmacy counter with a small naloxone kit, the pharmacist smiling, morning light. Pastel navy and mint. No pills or needles visible.", "A person collects a prescription at a pharmacy counter where a pharmacist smiles, a small naloxone kit on the counter.")},
 [DSM("Substance-Related and Addictive Disorders"), NSDUH, src("src-nida-naloxone", "Naloxone DrugFacts", "National Institute on Drug Abuse", "https://nida.nih.gov/publications/drugfacts/naloxone", note="Not opened."), NIDA_TX],
 ["Clinician to check medication statements.", "Confirm 'never use alone' line details per country before adding."], clin=True))

CARDS.append(sub_card("cannabis-use-disorder", "Cannabis Use Disorder", "When weed stops being a choice", ["marijuana use disorder", "cannabis dependence"], "F12.10 (mild) / F12.20 (moderate, severe)",
 "A pattern of cannabis use that a person can't control and keeps up despite harm, often with withdrawal when stopping.",
 "Cannabis is widely used and often seen as harmless, but some people develop a use disorder: using more than planned, failing to cut down, craving, needing it to feel normal, and continuing despite problems with motivation, memory, mood, money, or relationships. Withdrawal is real: irritability, poor sleep, anxiety, and low appetite for a week or two. Today's cannabis is often far stronger than in the past, and heavy use in the teens carries extra risks. It is treatable.",
 ["Everyone said you can't get addicted to weed. Then I tried to stop and couldn't sleep or eat for ten days.", "I wasn't 'wasting my life'. I just couldn't do anything without smoking first, and that scared me.", "r/leaves got me through the first month. Strangers who'd done it."],
 ["Using more or more often than intended", "Trying to cut down and not managing", "Needing cannabis to sleep, eat, relax, or feel normal", "Irritability, insomnia, anxiety, or low appetite when stopping", "Lost motivation, memory problems, or falling behind at school or work", "Continuing despite problems with mood, money, or relationships"],
 [{"myth": "Cannabis isn't addictive.", "fact": "Around 1 in 10 people who use cannabis develop a use disorder, and more among those who start young or use daily. Withdrawal is real."},
  {"myth": "It's natural, so it's safe.", "fact": "Modern high-THC products are potent. Heavy use, especially in the teens, raises the risk of psychosis, anxiety, and lasting effects on learning."},
  {"myth": "If it's legal, it can't be a problem.", "fact": "Legal status says nothing about whether use has become hard to control."}],
 {"plain": "Cannabis is the most widely used illicit drug in the US, with over 1 in 5 people using it in the past year. A significant minority of users develop a use disorder; exact figures to be confirmed.", "figure": "21.8% of people aged 12+ used cannabis in the past year (NSDUH 2023); cannabis use disorder prevalence to be confirmed from the same release", "source_ref": "src-nsduh-2023", "note": "The 2023 NSDUH cannabis use disorder figure was not confirmed in this session."},
 {"plain_summary": "Talking therapies are the main treatment: CBT, motivational enhancement therapy, and contingency management (rewards for staying off), often combined. Brief interventions help people who want to cut down. There is no approved medication for cannabis use disorder itself, though a doctor may treat sleep or mood problems during withdrawal. Peer support online and in groups helps many people through the early weeks.",
  "evidence_based_options": ["CBT and motivational enhancement therapy", "Contingency management", "Brief interventions and guided self-help", "Treatment of co-occurring anxiety, depression, or psychosis"],
  "self_help_that_supports_care": ["Planning for the first two weeks: sleep will be rough, then it improves", "Removing paraphernalia and changing routines around use", "Exercise, which helps withdrawal sleep and mood", "Peer communities for quitting cannabis"],
  "guideline_refs": ["src-nida-treatment"]},
 "If you've tried to cut down and can't, need cannabis to function, or it's affecting school, work, mood, or motivation, talk to a doctor, a drug helpline, or a therapist. Seek help urgently if you experience paranoia, hearing voices, or confusion.",
 "Occasional use without loss of control or harm isn't a disorder. Medical cannabis taken as prescribed isn't a use disorder, though dependence can still develop.",
 "Most people who quit cannabis find the fog lifting within weeks and wonder why they waited.",
 "Teenage brains are more vulnerable to cannabis. Heavy use before age 18 is linked to a higher risk of use disorder, poorer school outcomes, and psychosis in those at risk. Family-based treatments work well for teens.",
 "Cannabis is legal, decriminalized, or strictly prohibited depending on country, which shapes stigma and access to help. In some cultures it has traditional or religious uses; the DSM's concern is loss of control and harm, not use itself.",
 [{"title": "Cannabis intoxication and withdrawal", "icd10cm_code": "F12.x20 / F12.x3 (varies)", "text": "Intoxication can include anxiety, paranoia, and, with high doses, brief psychotic symptoms. Withdrawal peaks in the first week and mostly resolves within two."},
  {"title": "Cannabis-induced psychosis", "text": "Heavy use can trigger psychotic symptoms, usually resolving with abstinence, but raising the risk of a lasting psychotic disorder in some people."}],
 ["substance-use-disorders-overview", "understanding-psychosis", "generalized-anxiety-disorder", "major-depressive-disorder", "insomnia-disorder", "adhd"],
 ["withdrawal", "craving", "tolerance", "cbt", "motivational-interviewing", "relapse-prevention"],
 {"ids": ["reddit-r-leaves", "smart-recovery-meetings", "virtual-na", "frank-uk", "samhsa-national-helpline"],
  "vis": ("Soft line illustration of a person on a morning walk with a dog, clear-headed, a calendar on the wall at home visible through a window with days crossed off. Pastel navy and green. No cannabis imagery.", "A person walks a dog on a bright morning, a calendar with days crossed off visible through a window.")},
 [DSM("Substance-Related and Addictive Disorders"), NSDUH, NIDA_TX, src("src-nida-cannabis", "Cannabis (Marijuana) DrugFacts", "National Institute on Drug Abuse", "https://nida.nih.gov/publications/drugfacts/cannabis-marijuana", note="Not opened.")],
 ["Confirm cannabis use disorder prevalence from NSDUH 2023."]))

CARDS.append(sub_card("stimulant-use-disorder", "Stimulant Use Disorder", "When cocaine or meth has taken control", ["cocaine use disorder", "methamphetamine use disorder", "amphetamine-type use disorder"], "F15.10 / F15.20 (amphetamine-type); F14.10 / F14.20 (cocaine)",
 "A pattern of using cocaine, methamphetamine, or similar stimulants that a person can't control despite serious harm.",
 "Stimulants like cocaine, crack, methamphetamine, and non-prescribed amphetamines produce intense energy and euphoria followed by a crash. A use disorder develops when use becomes compulsive: binges, cravings, needing more, and carrying on despite damage to the heart, mood, money, relationships, and safety. The crash can bring severe depression and suicidal thoughts. There's no medication yet that treats stimulant use disorder directly, but behavioural treatments work, and people do recover.",
 ["The first line was the best I'd ever felt. Everything after was chasing it.", "The crash after a binge was the darkest place I've been. That's when I was most at risk.", "Contingency management sounds patronizing. Getting a reward for a clean test every week is what kept me showing up."],
 ["Binges: using heavily for hours or days, then crashing", "Cravings and needing more for the same effect", "Weight loss, poor sleep, racing heart, dental problems", "Paranoia, agitation, or seeing or hearing things during heavy use", "Deep depression and exhaustion after use", "Continuing despite harm to health, money, work, or relationships"],
 [{"myth": "Stimulants aren't physically addictive, so it's just willpower.", "fact": "Stimulants powerfully change the brain's reward system. The psychological pull is as real as any physical dependence."},
  {"myth": "There's no treatment for meth or cocaine addiction.", "fact": "Behavioural treatments, especially contingency management and CBT, have good evidence. Medication research is ongoing."},
  {"myth": "Prescribed ADHD medication is the same as meth.", "fact": "ADHD stimulants taken as prescribed and monitored are safe and effective. The problem is misuse, not the medicine."}],
 {"plain": "Stimulant use disorders affect a few million people in the US. Methamphetamine-related deaths have risen sharply in recent years, often involving fentanyl.", "figure": "NSDUH 2023 reports separate figures for cocaine and methamphetamine use disorders; to be confirmed from the release", "source_ref": "src-nsduh-2023", "note": "Specific figures not confirmed in this session."},
 {"plain_summary": "Contingency management, which gives tangible rewards for verified abstinence, has the strongest evidence for stimulant use disorder. CBT, the community reinforcement approach, and motivational interviewing also help. There's no approved medication yet, though research is active and a doctor may treat depression, sleep, or psychosis during recovery. Harm reduction, including drug checking for fentanyl and naloxone, saves lives. Peer support and structured daily routines matter a lot in early recovery.",
  "evidence_based_options": ["Contingency management", "CBT and the community reinforcement approach", "Motivational interviewing and peer support", "Harm reduction: fentanyl test strips and naloxone, via official services"],
  "self_help_that_supports_care": ["Expecting the crash and planning support for it", "Sleep, food, and structure in the first weeks", "Avoiding the people and places tied to use", "Meetings, including Cocaine Anonymous, Crystal Meth Anonymous, and SMART Recovery"],
  "guideline_refs": ["src-nida-treatment"]},
 "If stimulant use is becoming hard to control, or the crashes are bringing dark thoughts, talk to a doctor, a drug helpline, or a treatment service. Get emergency help for chest pain, seizures, very high temperature, or severe agitation or paranoia.",
 "Taking prescribed stimulant medication for ADHD as directed isn't a use disorder. Occasional use without loss of control is risky but isn't a diagnosis.",
 "People recover from stimulant use disorder. Brain function and mood improve steadily over months of abstinence, and the colour comes back.",
 "Stimulant use in teens often involves misused ADHD medication or study drugs. Family-involved treatment and honest information work better than scare tactics.",
 "Methamphetamine use is concentrated in some regions and communities, including among gay and bisexual men in some cities, where tailored services exist. Stigma around 'meth' is extreme and keeps people from help.",
 [{"title": "Stimulant intoxication and withdrawal", "text": "Intoxication can cause dangerous heart effects, overheating, seizures, and psychosis. Withdrawal ('the crash') brings exhaustion, hunger, and depression that can be severe."}],
 ["substance-use-disorders-overview", "understanding-psychosis", "major-depressive-disorder", "adhd", "opioid-use-disorder", "suicidal-thoughts-and-behavior"],
 ["craving", "withdrawal", "harm-reduction", "naloxone", "twelve-step", "smart-recovery", "stimulant-medication"],
 {"ids": ["smart-recovery-meetings", "virtual-na", "samhsa-national-helpline", "frank-uk"],
  "vis": ("Soft line illustration of a person cooking a simple meal in a tidy kitchen with music playing, a weekly planner on the fridge with ticks. Pastel navy and coral. No drug imagery.", "A person cooks a simple meal in a tidy kitchen, a weekly planner with ticks on the fridge.")},
 [DSM("Substance-Related and Addictive Disorders"), NSDUH, NIDA_TX, src("src-nida-meth", "Methamphetamine DrugFacts", "National Institute on Drug Abuse", "https://nida.nih.gov/publications/drugfacts/methamphetamine", note="Not opened.")],
 ["Confirm stimulant use disorder prevalence.", "Verify Cocaine Anonymous and Crystal Meth Anonymous online meeting pages before listing."]))

CARDS.append(sub_card("tobacco-use-disorder", "Tobacco Use Disorder", "Nicotine: the hardest easy thing to quit", ["nicotine dependence", "smoking", "vaping dependence"], "Z72.0 (mild) / F17.20x (moderate, severe)",
 "Dependence on nicotine from cigarettes, vapes, or other tobacco, with cravings, withdrawal, and failed attempts to stop.",
 "Nicotine is one of the most addictive substances there is, and tobacco use disorder is one of the most common. Most smokers want to quit and have tried. Withdrawal brings irritability, poor concentration, low mood, and strong cravings for a few weeks. Vaping delivers nicotine too and can create the same dependence, especially in young people. Smoking is the top preventable cause of death; quitting at any age adds years. Support plus medication roughly triples the chance of success.",
 ["I quit a hundred times. The hundred-and-first was the one with patches and a quit line.", "Vaping was supposed to be the way out. It became its own trap.", "Three years smoke-free. I still get the odd craving. It passes in a minute."],
 ["Smoking or vaping within an hour of waking", "Cravings and irritability when unable to use", "Repeated failed attempts to quit", "Using despite health problems or a doctor's advice", "Giving up activities where you can't smoke or vape"],
 [{"myth": "Nicotine replacement is as bad as smoking.", "fact": "It's the smoke, not the nicotine, that causes most of the harm. Patches, gum, and sprays are safe and double quit rates."},
  {"myth": "I've smoked too long for quitting to help.", "fact": "Quitting at any age improves health quickly, and benefits keep growing for years."},
  {"myth": "Vaping is harmless.", "fact": "Vaping is less harmful than smoking for adults who switch completely, but it's not harmless, and it's addictive, especially for young people who never smoked."}],
 {"plain": "About 1 in 9 US adults smokes cigarettes, down from 1 in 5 twenty years ago. Vaping has risen, especially among young adults.", "figure": "About 11% of US adults smoked cigarettes in recent CDC surveys; figures to be confirmed", "source_ref": "src-cdc-tobacco", "note": "Current CDC figure not confirmed in this session."},
 {"plain_summary": "Three things work: behavioural support (quit lines, apps, counselling), nicotine replacement (patches, gum, lozenges, sprays, combined), and prescription medicines such as varenicline or bupropion, prescribed and monitored by a doctor. Using support plus medication together gives the best chance. Some health services also offer vaping as a route off cigarettes for adults. Each quit attempt teaches something, and most people need several.",
  "evidence_based_options": ["Behavioural support: quit lines, text programmes, counselling", "Nicotine replacement therapy, often a patch plus a fast-acting product", "Varenicline or bupropion, prescribed and monitored by a doctor", "Combined support and medication, which works best"],
  "self_help_that_supports_care": ["Setting a quit date and telling people", "Changing the routines tied to smoking: coffee, breaks, after meals", "Delaying each craving by a few minutes; they pass", "Quit-smoking apps and online communities"],
  "guideline_refs": ["src-nice-ng209"]},
 "If you smoke or vape and want to stop, ask a doctor, pharmacist, or quit line about support and medication; it's free in many countries. If you've tried before, that's normal; the next attempt is more likely to work with help.",
 "Occasional social smoking without dependence isn't a disorder, though it still carries harm. Nicotine replacement used as directed isn't a disorder.",
 "Over half of all the people who have ever smoked have quit. You can be one of them.",
 "Most adult smokers started as teens. Vaping has created a new generation of nicotine-dependent young people. Teens respond to support that respects them and to honest information about dependence.",
 "Smoking rates vary enormously by country, gender, and income, and tobacco companies target lower-income communities and countries. Smokeless tobacco and water pipes carry their own risks and are common in parts of South Asia and the Middle East.",
 [{"title": "Tobacco withdrawal", "icd10cm_code": "F17.203", "text": "Irritability, anxiety, poor concentration, increased appetite, restlessness, and low mood, peaking in the first week and fading over weeks."}],
 ["substance-use-disorders-overview", "major-depressive-disorder", "schizophrenia", "generalized-anxiety-disorder"],
 ["withdrawal", "craving", "dependence", "relapse-prevention"],
 {"ids": ["reddit-r-stopsmoking", "smart-recovery-meetings"],
  "vis": ("Soft line illustration of a person at a bus stop breathing in fresh air with eyes closed, a quit-app counter on their phone showing days, trees behind. Pastel navy and sky blue. No cigarettes.", "A person breathes fresh air with eyes closed at a bus stop, a quit-app counter on their phone.")},
 [DSM("Substance-Related and Addictive Disorders"), src("src-cdc-tobacco", "Smoking and Tobacco Use: Data and Statistics", "CDC", "https://www.cdc.gov/tobacco/data_statistics/index.htm", note="Not opened; URL may have changed."), src("src-nice-ng209", "Tobacco: preventing uptake, promoting quitting and treating dependence (NG209)", "NICE", "https://www.nice.org.uk/guidance/ng209", 2021, note="Not opened.")],
 ["Confirm CDC prevalence and URL.", "Add verified quit lines per country (US 1-800-QUIT-NOW, NHS Smokefree, Quitline AU, India's QuitLine) once numbers are checked."], sens={"sensitivity_level": "standard", "show_crisis_strip": False, "content_notes": ["No sourcing or 'how to use' detail. Site-wide crisis link stays one tap away."]}))

CARDS.append(sub_card("sedative-hypnotic-anxiolytic-use-disorder", "Sedative, Hypnotic, or Anxiolytic Use Disorder", "When sleeping pills or benzos have taken control", ["benzodiazepine dependence", "benzo addiction", "Z-drug dependence"], "F13.10 (mild) / F13.20 (moderate, severe)",
 "A pattern of using benzodiazepines, sleeping tablets, or similar sedatives that a person can't control, often starting from a prescription.",
 "Benzodiazepines (like diazepam or alprazolam) and 'Z-drug' sleeping tablets calm anxiety and bring sleep quickly, which is why they're useful short-term and risky long-term. Dependence can develop within weeks even at prescribed doses. A use disorder means use has become hard to control, with craving, escalating amounts, and withdrawal. Stopping suddenly after regular use can cause seizures and can be fatal, so coming off must be gradual and medically supervised. Mixed with alcohol or opioids, sedatives can stop breathing.",
 ["My doctor prescribed them for panic. Two years later I couldn't get through a day without them.", "I tried to stop on my own and had a seizure. Nobody had told me that could happen.", "The taper took eight months. Slow. Boring. It worked, and my anxiety is better than it was on the pills."],
 ["Needing more for the same calming or sleep effect", "Anxiety, insomnia, shaking, or panic between doses or when stopping", "Running out early, using more than prescribed, or getting them from more than one source", "Using to cope with everyday stress rather than as prescribed", "Memory gaps, drowsiness, falls, or accidents", "Continuing despite harm or a doctor's advice"],
 [{"myth": "If a doctor prescribed it, it can't be addictive.", "fact": "Benzodiazepines and Z-drugs can cause dependence within weeks, even when taken exactly as prescribed. That's why guidelines limit them to short courses."},
  {"myth": "I'll just stop taking them.", "fact": "Sudden stopping after regular use can cause seizures and severe withdrawal. Tapering slowly under medical supervision is essential."},
  {"myth": "Benzos are safe to mix with a drink.", "fact": "Combined with alcohol or opioids, sedatives can stop breathing. This combination is involved in many overdose deaths."}],
 {"plain": "Prescription sedative misuse affects a few million people in the US each year, and dependence is common among long-term users at any dose.", "figure": "NSDUH reports past-year prescription tranquilizer or sedative misuse and use disorder; figures to be confirmed", "source_ref": "src-nsduh-2023", "note": "Specific figures not confirmed in this session."},
 {"plain_summary": "The core of treatment is a slow, medically supervised taper, sometimes switching to a longer-acting medicine first, over weeks to many months. CBT helps with the anxiety or insomnia the drug was treating and with the taper itself. Treating the underlying condition with safer long-term options, like therapy or antidepressants, prescribed and monitored by a doctor, makes stopping stick. Peer support, including online taper communities, helps people through a slow process.",
  "evidence_based_options": ["Gradual, medically supervised tapering", "CBT for anxiety or insomnia alongside the taper", "Safer long-term treatment of the underlying condition", "Peer support during tapering"],
  "self_help_that_supports_care": ["Never stopping suddenly; always with a plan from a doctor", "Keeping a simple diary of doses and symptoms during a taper", "Learning non-drug ways to manage anxiety and sleep before and during", "Telling people close to you what's happening"],
  "guideline_refs": ["src-nice-benzo"]},
 "If you've been taking sedatives or sleeping tablets for more than a few weeks and feel you can't stop, or you're using more than prescribed, talk to your doctor about a taper; don't stop on your own. Get emergency help for seizures, severe confusion, or if someone is unresponsive after mixing sedatives with alcohol or opioids.",
 "Taking a short prescribed course as directed isn't a disorder. Long-term prescribed use with dependence but no loss of control is a medical issue to taper, not a use disorder.",
 "Coming off sedatives is slow but very achievable, and most people find their anxiety and sleep are better off them in the end.",
 "Prescription sedatives are among the most commonly misused medicines among teenagers, often from family supplies and often mixed with alcohol. Counterfeit pills containing fentanyl are a growing danger.",
 "Prescribing rates and availability differ widely; in some countries benzodiazepines are sold without prescription. Older adults are prescribed them at high rates worldwide, with extra risk of falls and memory problems.",
 [{"title": "Sedative intoxication and withdrawal", "icd10cm_code": "F13.x20 / F13.x3 (varies)", "text": "Intoxication resembles drunkenness and can suppress breathing with other depressants. Withdrawal ranges from anxiety and insomnia to seizures and delirium, and requires medical supervision."}],
 ["substance-use-disorders-overview", "alcohol-use-disorder", "opioid-use-disorder", "generalized-anxiety-disorder", "panic-disorder", "insomnia-disorder"],
 ["benzodiazepine", "dependence", "withdrawal", "tapering", "sleep-medication", "cbt-i"],
 {"ids": ["smart-recovery-meetings", "virtual-na", "samhsa-national-helpline", "frank-uk"],
  "vis": ("Soft line illustration of a person and a doctor looking together at a gentle downward-sloping line on a calendar chart, a cup of herbal tea, a window with evening light. Pastel navy and lilac. No pills.", "A person and a doctor look together at a gently sloping chart on a calendar, a cup of tea beside them.")},
 [DSM("Substance-Related and Addictive Disorders"), NSDUH, src("src-nice-benzo", "Medicines associated with dependence or withdrawal symptoms: safe prescribing and withdrawal management for adults (NG215)", "NICE", "https://www.nice.org.uk/guidance/ng215", 2022, note="Not opened."), NIDA_TX],
 ["Confirm NSDUH figures.", "Clinician to check taper wording."], clin=True))

CARDS.append(sub_card("hallucinogen-related-disorders", "Hallucinogen-Related Disorders", "LSD, mushrooms, ketamine, PCP: when use becomes a problem", ["psychedelic use disorder", "PCP use disorder", "HPPD (hallucinogen persisting perception disorder)"], "F16.10 / F16.20",
 "Harm from drugs like LSD, magic mushrooms, ketamine, or PCP: losing control of use, or lasting changes in vision.",
 "Hallucinogens change how you see, think, and feel. Most people who use them don't lose control of their use. That is rare with LSD and mushrooms and more common with PCP and ketamine. The harms are frightening or dangerous trips, setting off psychosis in people at risk, and HPPD, where visual changes go on long after use. Ketamine can also damage the bladder. This card is about harm, not about the medical trials of psychedelic treatments.",
 ["The trip itself was fine. The visual snow six months later wasn't.", "Ketamine went from weekends to every day without me noticing the line.", "I didn't think you could get hooked on it. The bladder pain is what finally got me into treatment."],
 ["Using more or more often than intended, especially with ketamine or PCP", "Cravings or continuing despite problems", "Risky behaviour or injuries while high", "Lasting visual disturbances (trails, halos, 'visual snow') after use has stopped", "Paranoia, panic, or psychotic symptoms during or after use", "With ketamine: bladder pain, trouble peeing, memory problems"],
 [{"myth": "Psychedelics can't be addictive, so there's no risk.", "fact": "Classic psychedelics rarely cause dependence, but ketamine and PCP can, and all of them can trigger dangerous reactions or psychosis in some people."},
  {"myth": "A bad trip means permanent damage.", "fact": "Most bad trips pass within hours with a calm setting. Lasting problems are uncommon, and HPPD is treatable."},
  {"myth": "If researchers are studying psychedelics for depression, self-medicating is fine.", "fact": "Clinical trials use screened participants, known doses, and trained support. None of that is true of unsupervised use."}],
 {"plain": "Losing control of hallucinogen use is uncommon compared with other drugs. HPPD is rare. It affects a small minority of people who have used these drugs.", "figure": "DSM-5-TR text: 12-month prevalence of other hallucinogen use disorder about 0.1% of adults; HPPD estimated at around 4% of hallucinogen users in older studies", "source_ref": "src-dsm", "note": "Figures from the DSM-5-TR text; need primary sources."},
 {"plain_summary": "Treatment is the same as for other drug problems: talk therapy such as CBT, help with motivation, and peer support. Bladder damage from ketamine needs medical care. HPPD is treated with reassurance, staying off hallucinogens and cannabis, and sometimes medication, prescribed and monitored by a doctor. Psychosis that doesn't settle needs a mental health assessment. A frightening trip is managed in a calm, safe place with medical help if needed.",
  "evidence_based_options": ["CBT and motivational interviewing for ketamine or PCP use disorder", "Medical assessment and treatment for ketamine bladder damage", "Assessment and care for persisting psychotic symptoms", "Reassurance, abstinence, and sometimes medication for HPPD, prescribed and monitored by a doctor"],
  "self_help_that_supports_care": ["Stopping all hallucinogens and cannabis if HPPD symptoms appear", "Never using alone or in an unsafe place", "Telling a doctor about bladder symptoms early", "Peer support with others who've stopped"],
  "guideline_refs": ["src-nida-treatment"]},
 "If ketamine or PCP use is getting hard to control, if visual changes won't go away, or if paranoia or voices carry on after use, talk to a doctor or a drug helpline. Get emergency help for severe agitation, a high temperature, or someone who won't wake up.",
 "Having used a hallucinogen, even having had a bad trip, isn't a disorder. Ketamine given by a doctor for depression is a treatment, not a use disorder.",
 "Lasting harm from these drugs is uncommon. When it happens, people recover with time away from the drug and support.",
 "Ketamine use has grown among young people in several countries, with bladder damage appearing in people in their early twenties. Honest information works better than scare tactics.",
 "Some of these drugs have a long history of ceremonial use in Indigenous cultures. The DSM does not count that as a disorder. Problem use differs by country: ketamine in parts of Asia and the UK, PCP in some US cities.",
 [{"title": "Phencyclidine (PCP) use disorder and intoxication", "icd10cm_code": "F16.10 / F16.20; F16.x20", "text": "PCP can cause dangerous agitation, violence, and injuries during intoxication, and dependence is more common than with classic psychedelics."},
  {"title": "Hallucinogen persisting perception disorder", "icd10cm_code": "F16.983", "text": "Re-experiencing visual disturbances, like trails, halos, or 'visual snow', long after use has stopped, causing distress. Uncommon and treatable."}],
 ["substance-use-disorders-overview", "understanding-psychosis", "cannabis-use-disorder", "depersonalization-derealization-disorder", "major-depressive-disorder"],
 ["hallucination", "psychedelic-assisted-therapy", "ketamine-esketamine", "harm-reduction"],
 {"ids": ["smart-recovery-meetings", "virtual-na", "frank-uk", "samhsa-national-helpline"],
  "vis": ("Soft line illustration of a person sitting on a hill at dusk with a friend, the sky in soft natural colours, a flask of tea between them. Pastel navy and violet. No psychedelic patterns or drug imagery.", "Two friends sit on a hill at dusk under a softly coloured sky with a flask of tea between them.")},
 [DSM("Substance-Related and Addictive Disorders"), NIDA_TX, src("src-nida-hallucinogens", "Psychedelic and Dissociative Drugs", "National Institute on Drug Abuse", "https://nida.nih.gov/research-topics/psychedelic-dissociative-drugs", note="Not opened.")],
 ["Find primary prevalence sources for hallucinogen use disorder and HPPD."]))

CARDS.append(sub_card("inhalant-use-disorder", "Inhalant Use Disorder", "Sniffing glue, gas, or aerosols: a hidden danger", ["solvent misuse", "volatile substance misuse", "huffing"], "F18.10 (mild) / F18.20 (moderate, severe)",
 "Repeated inhaling of fumes from glue, petrol, aerosols, or similar products in a pattern that's hard to control and harmful.",
 "Inhalants are everyday products, like glue, aerosols, petrol, and gas, whose fumes are breathed in for a short high. They are cheap and legal, so use is most common among young teens and in poverty. Inhalant use disorder means use has become hard to control and is causing harm. The danger is acute: a single session can cause 'sudden sniffing death' from heart rhythm problems, and long-term use damages the brain, liver, kidneys, and nerves. Adults often miss it.",
 ["I was twelve. It was in every garage. Nobody thought to warn us.", "The headaches and the shaking hands came on slowly. I thought I was just tired.", "Getting out meant getting out of the group. A youth worker made that possible."],
 ["Chemical smells on breath or clothes, paint or glue stains on hands or face", "Empty aerosol cans, glue tubes, or rags hidden away", "Drunken, slurred behaviour that passes within an hour", "Sores around the mouth and nose, nosebleeds, red eyes", "Headaches, nausea, poor concentration, mood changes", "Continuing despite harm or trouble at school or home"],
 [{"myth": "It's just kids messing about with glue.", "fact": "Inhalants can kill on the first use through heart arrhythmia, and regular use causes lasting brain damage. It's never harmless."},
  {"myth": "Legal products can't be dangerous drugs.", "fact": "The products are legal; inhaling them is among the most dangerous forms of drug use."},
  {"myth": "Only poor kids do it.", "fact": "Inhalant use happens across all backgrounds, though it's more common where other drugs aren't accessible and supervision is low."}],
 {"plain": "Inhalant use is most common among younger teenagers and declines with age; the disorder itself is uncommon in adults.", "figure": "DSM-5-TR text: about 0.4% of 12–17-year-olds reported past-year inhalant use disorder in older US surveys; rare in adults", "source_ref": "src-dsm", "note": "Needs a current primary source."},
 {"plain_summary": "Treatment is mainly behavioural and social: CBT, motivational interviewing, family therapy for young people, and addressing the circumstances, like boredom, peer groups, or home problems, that drive use. Medical assessment checks for damage to the heart, nerves, liver, and kidneys. There's no medication for inhalant use disorder. Because users are often young and isolated, youth workers and schools are important partners.",
  "evidence_based_options": ["CBT and motivational interviewing", "Family therapy and youth outreach for young people", "Medical assessment for organ and nerve damage", "Treatment of co-occurring mental health conditions"],
  "self_help_that_supports_care": ["Removing or locking away products at home, calmly, not punitively", "Finding activities and groups that replace the time and company", "Talking to a trusted adult or a helpline", "Knowing the emergency signs: collapse, chest pain, seizures"],
  "guideline_refs": ["src-nida-treatment"]},
 "If you or a young person you know is inhaling fumes to get high, talk to a doctor, a drug helpline, or a youth service soon. Call emergency services immediately if someone collapses, has chest pain, or has a seizure during or after use.",
 "Accidental exposure to fumes at work or home isn't a use disorder. Nitrous oxide ('laughing gas') and nitrites ('poppers') are classified separately by the DSM under other substances.",
 "Young people who stop inhaling recover much of what was lost, and the earlier they stop, the more comes back.",
 "This is overwhelmingly a young teenager's problem, with use often starting around 12 to 14. Schools, parents, and youth services are the front line, and open conversation beats shock tactics.",
 "Inhalant use is a serious problem among street-connected children in many countries and in some remote Indigenous communities, where community-led programmes and limiting access to products have made a difference.",
 [{"title": "Inhalant intoxication", "icd10cm_code": "F18.x20 (varies)", "text": "Brief drunkenness, dizziness, slurred speech, and sometimes hallucinations, lasting minutes to an hour. Can cause sudden death from heart rhythm disturbance."}],
 ["substance-use-disorders-overview", "conduct-disorder", "major-depressive-disorder", "housing-and-money-problems", "neurocognitive-disorder-other-causes"],
 ["intoxication", "craving", "harm-reduction"],
 {"ids": ["frank-uk", "samhsa-national-helpline", "smart-recovery-meetings"],
  "vis": ("Soft line illustration of a youth worker and a teenager repairing a bike together in a community workshop, tools on the wall, afternoon light. Pastel navy and orange. No inhalant products.", "A youth worker and a teenager repair a bike together in a community workshop.")},
 [DSM("Substance-Related and Addictive Disorders"), NIDA_TX, src("src-nida-inhalants", "Inhalants DrugFacts", "National Institute on Drug Abuse", "https://nida.nih.gov/publications/drugfacts/inhalants", note="Not opened.")],
 ["Find a current prevalence source.", "Identify youth-specific helplines per country."]))

CARDS.append(sub_card("caffeine-related-disorders", "Caffeine-Related Disorders", "Too much coffee, or the headache when you stop", ["caffeine intoxication", "caffeine withdrawal"], "F15.920 / F15.93",
 "Problems from caffeine: intoxication after too much, or withdrawal symptoms like headache and tiredness when stopping.",
 "Caffeine is the world's most used psychoactive substance, and for most people it's fine. The DSM recognizes two caffeine problems: intoxication, when a large amount causes restlessness, racing heart, insomnia, stomach upset, and anxiety; and withdrawal, when a regular user stops and gets headache, tiredness, low mood, and poor concentration for a few days. Energy drinks and caffeine powders make intoxication more likely. 'Caffeine use disorder' is listed as a condition for further study, not an official diagnosis.",
 ["Four energy drinks before an exam and I thought I was having a heart attack.", "I didn't know the Monday headaches were because I skipped coffee at weekends.", "Cutting down slowly over two weeks was the trick. No headache, better sleep."],
 ["After a lot of caffeine: restlessness, nervousness, racing heart, insomnia, upset stomach, muscle twitches", "After stopping: headache, marked tiredness, low mood, irritability, trouble concentrating", "Withdrawal starting within a day of the last caffeine and lasting a few days", "Symptoms causing real distress or disruption"],
 [{"myth": "Caffeine isn't a drug.", "fact": "It's a stimulant with real intoxication and withdrawal syndromes, both recognized by the DSM."},
  {"myth": "Caffeine withdrawal is just being a bit grumpy.", "fact": "For regular users, withdrawal headaches and exhaustion can be bad enough to miss work, which is why cutting down gradually helps."},
  {"myth": "Energy drinks are the same as coffee.", "fact": "Energy drinks and caffeine powders can deliver very large amounts quickly, which is where most serious caffeine intoxication comes from, especially in young people."}],
 {"plain": "Most adults use caffeine daily. Intoxication is uncommon but rising with energy drinks; withdrawal symptoms affect a large share of regular users who stop suddenly.", "figure": "DSM-5-TR text: around 7% of caffeine users may have intoxication symptoms in a year; about half of regular users report headache on abrupt stopping", "source_ref": "src-dsm", "note": "Figures from the DSM-5-TR text; need primary citations."},
 {"plain_summary": "Intoxication is managed by stopping caffeine and, rarely, medical care for very high intakes. Withdrawal is prevented by cutting down gradually over a week or two rather than stopping dead; simple painkillers and rest help if it happens. Anyone with anxiety, panic, or insomnia is often advised to reduce caffeine, as it worsens all three. No specialist treatment is needed for most people.",
  "evidence_based_options": ["Gradual reduction to avoid withdrawal", "Medical care for severe intoxication, especially from powders or many energy drinks", "Reducing caffeine as part of treatment for anxiety, panic, and insomnia"],
  "self_help_that_supports_care": ["Knowing how much caffeine is in what you drink", "Swapping one drink a day to decaf, then another", "No caffeine after early afternoon if sleep is a problem", "Avoiding caffeine powders and limiting energy drinks"],
  "guideline_refs": ["src-dsm"]},
 "Get medical help if someone has a racing or irregular heartbeat, chest pain, vomiting, or confusion after a lot of caffeine, especially from powders or energy drinks. Talk to a doctor if caffeine seems tied to anxiety, panic, or insomnia.",
 "Enjoying coffee daily isn't a disorder. Feeling a bit tired without it isn't withdrawal unless it causes real distress.",
 "Caffeine problems are easy to fix. Most people feel better within a couple of weeks of adjusting their intake.",
 "Energy drinks are heavily marketed to teenagers, and emergency visits for caffeine intoxication in young people have risen. Several countries restrict sales to minors.",
 "Coffee, tea, yerba mate, kola, and guarana are woven into cultures worldwide. Typical intake varies hugely, and what counts as 'a lot' depends on where you are.",
 [{"title": "Caffeine use disorder (Section III)", "text": "A proposed diagnosis for people who can't cut down despite harm. It's being studied and is not an official diagnosis; see its own card."}],
 ["caffeine-use-disorder", "generalized-anxiety-disorder", "panic-disorder", "insomnia-disorder"],
 ["intoxication", "withdrawal", "sleep-hygiene"],
 {"ids": [], "vis": ("Soft line illustration of a person enjoying a single cup of coffee on a quiet porch in the morning, a glass of water beside it, birds on a wire. Pastel navy and cream.", "A person enjoys a single cup of coffee on a quiet morning porch with a glass of water beside it.")},
 [DSM("Substance-Related and Addictive Disorders")],
 ["Find primary sources for intoxication and withdrawal prevalence."], sens={"sensitivity_level": "standard", "show_crisis_strip": False, "content_notes": ["Site-wide crisis link stays one tap away."]}))

CARDS.append(sub_card("other-or-unknown-substance-use-disorder", "Other (or Unknown) Substance Use Disorder", "When the substance isn't on the usual list", ["novel psychoactive substances", "nitrous oxide", "anabolic steroids", "kratom", "'spice'", "GHB"], "F19.10 (mild) / F19.20 (moderate, severe)",
 "A use disorder involving a substance not covered by the other categories, or when the substance isn't known.",
 "Some substances don't fit the main DSM groups: nitrous oxide ('laughing gas'), GHB, anabolic steroids, kratom, betel nut, synthetic cannabinoids ('spice'), and new 'designer' drugs. The DSM uses this category for a use disorder involving any of these, or when a person doesn't know what they've been using. The patterns of loss of control and harm are the same; the specific dangers differ. New substances are often unpredictable, and official drug-checking services can tell you what's in something.",
 ["Nitrous was a party thing. Then the numbness in my legs started. The doctor said nerve damage.", "GHB has a tiny gap between a high and unconsciousness. I learned that the hard way.", "Steroids didn't feel like a drug problem until I couldn't stop and my moods were out of control."],
 ["Using a substance more or longer than intended, and failing to cut down", "Cravings, needing more, or withdrawal", "Continuing despite harm to health, mood, work, or relationships", "Substance-specific harms: nerve damage, collapse, mood swings, heart risk, or psychosis", "Not knowing what a substance contains"],
 [{"myth": "Legal highs and 'research chemicals' are safe because they're legal or new.", "fact": "New substances are often untested and unpredictable, and several have caused clusters of deaths. Legal status is not a safety rating."},
  {"myth": "Nitrous oxide is harmless.", "fact": "Heavy use damages nerves by depleting vitamin B12 and can cause lasting weakness and numbness."},
  {"myth": "Steroids aren't addictive.", "fact": "Anabolic steroid dependence is recognized, with withdrawal depression and strong difficulty stopping."}],
 {"plain": "Use of 'other' substances is less common than alcohol, cannabis, or opioids but has grown with new synthetic drugs and nitrous oxide, especially among young people.", "figure": "No single prevalence figure; varies by substance and country", "source_ref": "src-dsm"},
 {"plain_summary": "Treatment uses the same approaches as other substance use disorders: CBT, motivational interviewing, peer support, and treating co-occurring conditions, with medical care for the specific harms of each substance, such as B12 for nitrous oxide nerve damage or supervised withdrawal for GHB, which can be dangerous. Drug-checking services and harm-reduction advice from official organizations reduce the risk from unknown substances.",
  "evidence_based_options": ["CBT, motivational interviewing, and peer support", "Medical treatment for substance-specific harms", "Medically supervised withdrawal where needed (for example GHB)", "Harm reduction, including drug checking where available"],
  "self_help_that_supports_care": ["Finding out what a substance is before using, through official drug-checking services", "Never using alone", "Telling a doctor exactly what you've used; they're there to help, not judge", "Peer support, online or in person"],
  "guideline_refs": ["src-nida-treatment"]},
 "If use of any substance is becoming hard to control, or you've had frightening effects, talk to a doctor or a drug helpline. Get emergency help for collapse, seizures, severe agitation, or numbness and weakness that's spreading.",
 "Occasional use without loss of control isn't a disorder, though many of these substances carry serious acute risks. Prescribed medicines taken as directed aren't a use disorder.",
 "Recovery looks the same whatever the substance: support, time, and people who've been there.",
 "New synthetic substances and nitrous oxide are mostly used by young people, often without knowing what they're taking. Honest information and drug-checking services reduce deaths.",
 "What counts as 'other' depends on where you are: betel nut in South and Southeast Asia, khat in East Africa and the Middle East, and kratom in Southeast Asia all have traditional use and their own patterns of dependence.",
 None,
 ["substance-use-disorders-overview", "stimulant-use-disorder", "hallucinogen-related-disorders", "cannabis-use-disorder", "understanding-psychosis"],
 ["harm-reduction", "withdrawal", "intoxication"],
 {"ids": ["frank-uk", "samhsa-national-helpline", "smart-recovery-meetings", "virtual-na"],
  "vis": ("Soft line illustration of a person at a community health drop-in talking with a worker at a friendly information desk with leaflets, a plant, and a poster reading 'ask us anything'. Pastel navy and teal.", "A person talks with a worker at a friendly community health information desk with leaflets and a plant.")},
 [DSM("Substance-Related and Addictive Disorders"), NIDA_TX],
 ["Add country-specific drug-checking service links after verification."]))

CARDS.append(sub_card("gambling-disorder", "Gambling Disorder", "When betting has taken control", ["problem gambling", "compulsive gambling", "gambling addiction"], "F63.0",
 "Repeated gambling that a person can't stop or control, despite serious harm to money, relationships, and mental health.",
 "Gambling disorder is the only non-substance addiction in the main DSM. It involves needing to bet more for the same thrill, restlessness when cutting down, repeated failed attempts to stop, chasing losses, lying about it, and relying on others to bail you out. Online betting and apps make it available every second of the day. It carries one of the highest suicide risks of any mental health condition, and it's treatable, with therapy, peer support, and tools like self-exclusion.",
 ["It wasn't about the money. It was the only time the noise in my head stopped.", "I lost the house. Nobody knew until the letters came.", "Gamblers Anonymous was the first room where I didn't have to explain."],
 ["Needing to bet more for the same excitement", "Trying to cut down and feeling restless or irritable", "Chasing losses with more gambling", "Lying to family about gambling, or borrowing and hiding debts", "Gambling when stressed, low, or anxious", "Losing relationships, work, or money because of it"],
 [{"myth": "It's a money problem, not a mental health one.", "fact": "Gambling disorder changes the brain's reward system like a substance addiction. Debt is a result, not the core."},
  {"myth": "You can't be addicted to something with no substance.", "fact": "The DSM reclassified gambling disorder alongside substance addictions in 2013 because the brain and behaviour patterns are so similar."},
  {"myth": "One big win would fix it.", "fact": "Wins feed the disorder. Recovery means leaving gambling behind, not getting ahead."}],
 {"plain": "Around 1 in 100 adults has a severe gambling problem in a given year, and 2 to 3 in 100 have gambling problems of some degree, with higher rates in young men and online bettors.", "figure": "About 1% of US adults (2 million) meet criteria for severe gambling problems per year (NCPG); 2.4% of Great Britain adults scored as problem gamblers in 2025 (PGSI 8+)", "source_ref": "src-ncpg"},
 {"plain_summary": "CBT for gambling, which works on the thinking errors and urges that drive betting, has the best evidence, along with motivational interviewing. Peer groups like Gamblers Anonymous and SMART Recovery help many. Practical tools are powerful: self-exclusion schemes, gambling-blocking software, bank card blocks, and handing financial control to someone trusted for a while. Debt advice is part of treatment. Medication is sometimes used for urges, prescribed and monitored by a doctor. Family members benefit from their own support.",
  "evidence_based_options": ["CBT for gambling disorder and motivational interviewing", "Self-exclusion schemes, blocking software, and bank gambling blocks", "Peer support: Gamblers Anonymous, SMART Recovery, and gambling helplines", "Debt advice and support for family members"],
  "self_help_that_supports_care": ["Blocking gambling on your bank card and phone today", "Self-excluding from online and local venues", "Telling one person the real numbers", "Calling a gambling helpline; most are free and confidential"],
  "guideline_refs": ["src-ncpg"]},
 "If gambling is causing debt, secrecy, or distress, or you've tried to stop and can't, call a gambling helpline or talk to a doctor. If you're having thoughts of ending your life, which are common with gambling debt, use the crisis strip now. Debt can be dealt with; you can't be replaced.",
 "Occasional betting within limits isn't a disorder. Big losses during a bad patch are a warning sign but don't by themselves mean a disorder.",
 "People recover from gambling disorder and rebuild their finances and relationships. Many go on to help others out.",
 "Gambling-like features in video games (loot boxes) and easy access to betting apps mean problems are starting younger. Teens who gamble are at much higher risk of later disorder.",
 "Gambling norms and legality vary: central to social life in some cultures, forbidden in others. Online gambling has reached everywhere. Shame and the hiddenness of financial harm keep people from help across all communities.",
 None,
 ["substance-use-disorders-overview", "major-depressive-disorder", "alcohol-use-disorder", "suicidal-thoughts-and-behavior", "internet-gaming-disorder", "housing-and-money-problems"],
 ["craving", "relapse-prevention", "twelve-step", "smart-recovery", "cbt"],
 {"ids": ["reddit-r-problemgambling", "ncpg-helpline-us", "smart-recovery-meetings"],
  "vis": ("Soft line illustration of a person handing a bank card to a trusted friend across a kitchen table, both calm, a budgeting notebook open, sunlight. Pastel navy and gold. No cards, dice, or slot machines.", "A person hands a bank card to a trusted friend across a kitchen table beside an open budgeting notebook.")},
 [DSM("Substance-Related and Addictive Disorders"), src("src-ncpg", "1-800-GAMBLER National Problem Gambling Helpline fact sheet", "National Council on Problem Gambling (US)", "https://www.ncpgambling.org/wp-content/uploads/2023/12/1-800-GAMBLER-Fact-Sheet.pdf", 2023, seen=True),
  src("src-gb-gambling", "Gambling Survey for Great Britain (Gambling Commission)", "UK Gambling Commission", "https://www.gamblingcommission.gov.uk/statistics-and-research/", note="2025 figure (2.4% PGSI 8+) seen in a secondary summary; not opened."),
  src("src-nice-gambling", "Harmful gambling: identification, assessment and management (NG248)", "NICE", "https://www.nice.org.uk/guidance/ng248", 2025, note="Not opened; guideline number from memory.")],
 ["Verify GamCare (UK) and Gambling Help Online (AU) numbers before adding.", "Confirm NICE NG248 reference."]))

CARDS.append({
 "topic_id": "substance-medication-induced-mental-disorders", "official_name": "Substance/Medication-Induced Mental Disorders (explainer)", "plain_title": "When a substance or medicine causes the symptoms",
 "also_known_as": ["drug-induced psychosis", "alcohol-induced depression", "medication-induced anxiety"], "chapter_id": "substance", "card_type": "explainer", "icd10cm_code": "varies by substance and disorder", "language_convention": "person-first",
 "one_liner": "Depression, anxiety, psychosis, mania, sleep, or sexual problems caused directly by a substance or a medicine.",
 "in_simple_words": "Sometimes mental health symptoms are caused by a substance, during intoxication or withdrawal, or by a prescribed medicine. Heavy drinking can cause depression; stimulants or cannabis can cause psychosis; steroids can cause mania; some medicines cause anxiety or sleep problems. The DSM has a 'substance/medication-induced' version of most disorders. The key sign is timing: symptoms start with use and usually fade within a month of stopping. Treatment focuses on stopping or changing the substance, with support for the symptoms meanwhile.",
 "what_it_can_feel_like": ["The paranoia started after a weekend of heavy use and faded in two weeks. The doctor called it substance-induced. That mattered for what came next.", "I was told I had depression. It was the drinking. Three months sober and it lifted.", "A steroid prescription turned my husband into someone I didn't know for a month."],
 "common_signs": ["Symptoms that start during or soon after using a substance or starting a medicine", "Symptoms that are more than the usual effects of the substance", "Symptoms fading within about a month of stopping", "No history of the same symptoms before the substance", "Any disorder: depression, anxiety, psychosis, mania, sleep, sexual, or thinking problems"],
 "myths_vs_facts": [
  {"myth": "If a drug caused the psychosis, it isn't real psychosis.", "fact": "The symptoms are just as real and need care. 'Induced' tells you about the cause, not the seriousness."},
  {"myth": "Substance-induced means it will always go away on its own.", "fact": "Most cases improve with abstinence, but some, especially psychosis after heavy stimulant or cannabis use, continue and become a primary disorder. Follow-up matters."},
  {"myth": "Prescribed medicines can't cause mental health symptoms.", "fact": "Several can, including steroids, some heart and asthma medicines, and others. Tell your doctor about new symptoms after starting a medicine."}],
 "how_common": {"plain": "Substance-induced disorders are common in emergency and addiction settings. Exact rates depend on the substance and the symptom.",
  "figure": "No single figure; the DSM-5-TR gives rates by substance and disorder", "source_ref": "src-dsm"},
 "what_helps": {"plain_summary": "The main treatment is stopping, reducing, or changing the substance or medicine, safely and with medical advice. Symptoms are supported meanwhile: a safe setting and sometimes short-term medication for psychosis or severe agitation, prescribed and monitored by a doctor. If symptoms don't fade within a month of stopping, the diagnosis is reviewed and treated as a primary disorder. Treatment for the substance use disorder, if there is one, prevents it happening again.",
  "evidence_based_options": ["Stopping or changing the substance or medicine, with medical guidance", "Short-term symptom treatment where needed, prescribed and monitored by a doctor", "Reassessment if symptoms persist beyond a month", "Treatment for any underlying substance use disorder"],
  "self_help_that_supports_care": ["Telling clinicians honestly what you've taken, including prescribed and over-the-counter medicines", "Not stopping a prescribed medicine suddenly without advice", "Avoiding the substance while recovering", "Follow-up even when symptoms have gone"],
  "guideline_refs": ["src-dsm"]},
 "when_to_reach_out": "If mental health symptoms started after using a substance or starting a medicine, tell a doctor and say exactly what you've taken. Get urgent help for psychosis, severe agitation, confusion, or thoughts of ending your life.",
 "is_not": "The ordinary effects of a substance (being drunk, being high) aren't an induced disorder; it's when the symptoms go beyond that. Symptoms that were present before the substance, or that last long after stopping, point to a primary disorder.",
 "hope_note": "When the cause is a substance, stopping it often brings recovery faster than people expect.",
 "sub_sections": [
  {"title": "Which disorders have an induced version", "text": "Psychotic, bipolar, depressive, anxiety, obsessive-compulsive, sleep, sexual dysfunction, delirium, and neurocognitive disorders. Each is coded under the substance involved."},
  {"title": "Common culprits", "text": "Alcohol (depression, anxiety, psychosis, memory problems), stimulants and cannabis (psychosis, anxiety), steroids (mania, depression), sedatives and opioids (depression, delirium in withdrawal), and some prescribed medicines."}],
 "related_topics": ["substance-use-disorders-overview", "understanding-psychosis", "major-depressive-disorder", "bipolar-i-disorder", "delirium", "mental-disorders-due-to-another-medical-condition", "medication-induced-movement-disorders"],
 "glossary_terms": ["intoxication", "withdrawal", "psychosis", "differential-diagnosis", "side-effects"],
 "safety": ELEV(),
 "visual": VIS("Soft line illustration of a doctor and a person reviewing a short list together on a clipboard, a calendar with a month marked, calm consulting room. Pastel navy and sage. No pills visible.", "A doctor and a person review a short list on a clipboard beside a calendar with a month marked."),
 "communities": ["samhsa-national-helpline", "frank-uk", "smart-recovery-meetings"],
 "sources": [DSM("Substance-Related and Addictive Disorders"), NIDA],
 "review": REV(["Clinician to review the 'one month' framing and the list of culprits."], clin=True)})
